from collections import deque

n = 14
base_edges = [(0, 7), (0, 8), (0, 9), (1, 7), (1, 10), (1, 11), (2, 7), (2, 12), (2, 13), (3, 8), (3, 10), (3, 12), (4, 8), (4, 11), (4, 13), (5, 9), (5, 10), (5, 13), (6, 9), (6, 11), (6, 12)]

def build_adj(edges):
    adj = {i: set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj

def girth(adj):
    best = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            v = q.popleft()
            for nb in adj[v]:
                if dist[nb] == -1:
                    dist[nb] = dist[v] + 1
                    parent[nb] = v
                    q.append(nb)
                elif nb != parent[v]:
                    cycle_len = dist[v] + dist[nb] + 1
                    if cycle_len < best:
                        best = cycle_len
                        if best <= 5:
                            return best
    return best

# Check all possible additional edges
all_pairs = [(i,j) for i in range(n) for j in range(i+1,n) if (i,j) not in base_edges]
