import z3

n = 14
# Variables for edges
edge_vars = {}
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = z3.Bool(f"e_{i}_{j}")

s = z3.Solver()

# No 3-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(z3.Not(z3.And(edge_vars[(i,j)], edge_vars[(i,k)], edge_vars[(j,k)])))

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k == i or k == j: continue
            for l in range(k+1, n):
                if l == i or l == j: continue
                # cycle i-j-k-l-i
                # edges: (i,j), (j,k), (k,l), (l,i)
                e1 = edge_vars.get((i,j)) or edge_vars.get((j,i))
                e2 = edge_vars.get((j,k)) or edge_vars.get((k,j))
                e3 = edge_vars.get((k,l)) or edge_vars.get((l,k))
                e4 = edge_vars.get((l,i)) or edge_vars.get((i,l))
                if e1 is None or e2 is None or e3 is None or e4 is None: continue
                s.add(z3.Not(z3.And(e1, e2, e3, e4)))

# No 5-cycles
for i in range(n):
    for j in range(i+1, n):
        e1 = edge_vars[(i,j)]
        for k in range(n):
            if k == i or k == j: continue
            e2 = edge_vars[(min(j,k), max(j,k))]
            for l in range(n):
                if l in (i,j,k): continue
                e3 = edge_vars[(min(k,l), max(k,l))]
                for m in range(n):
                    if m in (i,j,k,l): continue
                    e4 = edge_vars[(min(l,m), max(l,m))]
                    e5 = edge_vars[(min(m,i), max(m,i))]
                    s.add(z3.Not(z3.And(e1, e2, e3, e4, e5)))

# At least 26 edges
edge_count = z3.Sum([z3.If(edge_vars[e], 1, 0) for e in edge_vars])
s.add(edge_count >= 26)

print("Constraints added. Solving...")
result = s.check()
print(result)
if result == z3.sat:
    model = s.model()
    edges = []
    for e, v in edge_vars.items():
        if z3.is_true(model[v]):
            edges.append(e)
    print(len(edges), "edges")
    print(sorted(edges))

import z3

n = 14
# Variables for edges
edge_vars = {}
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = z3.Bool(f"e_{i}_{j}")

def get_edge(i, j):
    return edge_vars[(min(i,j), max(i,j))]

s = z3.Solver()

# No 3-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(z3.Not(z3.And(get_edge(i,j), get_edge(i,k), get_edge(j,k))))

print("3-cycle constraints done")

# No 4-cycles
count4 = 0
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k == i or k == j: continue
            for l in range(k+1, n):
                if l == i or l == j: continue
                count4 += 1
                s.add(z3.Not(z3.And(get_edge(i,j), get_edge(j,k), get_edge(k,l), get_edge(l,i))))

print(f"4-cycle constraints: {count4}")

# No 5-cycles
count5 = 0
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k == i or k == j: continue
            for l in range(n):
                if l in (i,j,k): continue
                for m in range(n):
                    if m in (i,j,k,l): continue
                    count5 += 1
                    s.add(z3.Not(z3.And(get_edge(i,j), get_edge(j,k), get_edge(k,l), get_edge(l,m), get_edge(m,i))))

print(f"5-cycle constraints: {count5}")

# At least 26 edges
edge_count = z3.Sum([z3.If(edge_vars[e], 1, 0) for e in edge_vars])
s.add(edge_count >= 26)

print("Solving...")
result = s.check()
print(result)
if result == z3.sat:
    model = s.model()
    edges = []
    for e, v in edge_vars.items():
        if z3.is_true(model[v]):
            edges.append(e)
    print(len(edges), "edges")
    print(sorted(edges))

